fn lookup_mapping(table: &[(u32, u16)], cp: u32) -> Option<&'static [u32]> {
    table
        .binary_search_by_key(&cp, |(row_cp, _)| *row_cp)
        .ok()
        .map(|i| mapping(table[i].1))
}

pub fn canonical_decomposition(cp: u32) -> Option<&'static [u32]> {
    lookup_mapping(CANONICAL_DECOMP, cp)
}

pub fn compatibility_decomposition(cp: u32) -> Option<&'static [u32]> {
    lookup_mapping(COMPATIBILITY_DECOMP, cp)
}

pub fn canonical_combining_class(cp: u32) -> u8 {
    CCC.binary_search_by_key(&cp, |(row_cp, _)| *row_cp)
        .ok()
        .map(|i| CCC[i].1)
        .unwrap_or(0)
}

pub fn canonical_composition(starter: u32, combining: u32) -> Option<u32> {
    COMPOSITION
        .binary_search_by(|(a, b, _)| match a.cmp(&starter) {
            core::cmp::Ordering::Equal => b.cmp(&combining),
            ord => ord,
        })
        .ok()
        .map(|i| COMPOSITION[i].2)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn assert_mapping_table_sorted_and_bounded(name: &str, table: &[(u32, u16)]) {
        let mut previous_cp = None;
        for (index, &(cp, mapping)) in table.iter().enumerate() {
            assert!(
                cp <= 0x10FFFF,
                "{name}[{index}] exceeds Unicode scalar range"
            );
            assert!(
                usize::from(mapping) < UNIQUE_MAPPING_COUNT,
                "{name}[{index}] points outside mapping table"
            );
            if let Some(prev) = previous_cp {
                assert!(prev < cp, "{name}[{index}] is unsorted");
            }
            previous_cp = Some(cp);
        }
    }

    fn assert_ccc_table_sorted(name: &str, table: &[(u32, u8)]) {
        let mut previous_cp = None;
        for (index, &(cp, _)) in table.iter().enumerate() {
            assert!(
                cp <= 0x10FFFF,
                "{name}[{index}] exceeds Unicode scalar range"
            );
            if let Some(prev) = previous_cp {
                assert!(prev < cp, "{name}[{index}] is unsorted");
            }
            previous_cp = Some(cp);
        }
    }

    fn assert_composition_table_sorted(name: &str, table: &[(u32, u32, u32)]) {
        let mut previous_key = None;
        for (index, &(starter, combining, composed)) in table.iter().enumerate() {
            assert!(
                starter <= 0x10FFFF,
                "{name}[{index}] starter exceeds Unicode scalar range"
            );
            assert!(
                combining <= 0x10FFFF,
                "{name}[{index}] combining exceeds Unicode scalar range"
            );
            assert!(
                composed <= 0x10FFFF,
                "{name}[{index}] composed exceeds Unicode scalar range"
            );
            let key = (starter, combining);
            if let Some(prev) = previous_key {
                assert!(prev < key, "{name}[{index}] is unsorted");
            }
            previous_key = Some(key);
        }
    }

    #[test]
    fn normalization_binary_search_tables_are_sorted_and_mapping_bounded() {
        assert_eq!(UNICODE_VERSION, crate::UNICODE_VERSION);
        assert_mapping_table_sorted_and_bounded("CANONICAL_DECOMP", CANONICAL_DECOMP);
        assert_mapping_table_sorted_and_bounded("COMPATIBILITY_DECOMP", COMPATIBILITY_DECOMP);
        assert_ccc_table_sorted("CCC", CCC);
        assert_composition_table_sorted("COMPOSITION", COMPOSITION);
    }
}
